def circuit_breaker(max_failures=5, reset_timeout=10):
    """Simple Python decorator-style circuit breaker (per-process)."""
    import time
    from functools import wraps

    state = {
        'failures': 0,
        'opened_at': None,
        'state': 'CLOSED'
    }

    def decorator(fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            now = time.time()
            if state['state'] == 'OPEN':
                if now - state['opened_at'] < reset_timeout:
                    raise RuntimeError('CircuitOpen')
                else:
                    state['state'] = 'HALF_OPEN'

            try:
                result = fn(*args, **kwargs)
            except Exception:
                state['failures'] += 1
                if state['failures'] >= max_failures:
                    state['state'] = 'OPEN'
                    state['opened_at'] = time.time()
                raise
            else:
                # success
                state['failures'] = 0
                state['state'] = 'CLOSED'
                return result
        return wrapped
    return decorator

# usage
@circuit_breaker(max_failures=3, reset_timeout=5)
def call_remote():
    # call an HTTP service or DB
    pass
